                                                                                                                                                                                                              
  CREATE TABLE "CHECK_CHANGE_LIBRARY"                                                                                                                                                              
   (	"LIBRARY_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CONFIG_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                    
	"DEPT_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                      
	"AREA_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                      
	"IS_ENABLE" NUMBER(20,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                          
	"REMARKS" VARCHAR2(4000),                                                                                                                                                                                    
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                          
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                   
	"CREATION_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                        
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                   
	"UPDATED_DATE" DATE,                                                                                                                                                                                         
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                                 
	 PRIMARY KEY ("LIBRARY_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                         
   ) ;                                                                                                                                                                                                        

